UPDATE model_usage
SET tenant_id = #{tenantId}, user_id = #{userId}, session_id = #{sessionId}, message_id = #{messageId}, agent_id = #{agentId}, agent_name = #{agentName}, app_name = #{appName}, invocation_id = #{invocationId}, provider = #{provider}, model_version = #{modelVersion}, prompt_tokens = #{promptTokens}, candidate_tokens = #{candidateTokens}, total_tokens = #{totalTokens}, thoughts_tokens = #{thoughtsTokens}, tool_use_prompt_tokens = #{toolUsePromptTokens}, trace_id = #{traceId}, metadata = #{metadata}
WHERE id = #{id} AND deleted = 0

