SELECT  FROM model_usage
WHERE user_id=#{userId} AND create_time >= DATE_SUB(CURRENT_TIMESTAMP(3), INTERVAL #{days} DAY) AND deleted=0
AND (tenant_id IS NULL OR tenant_id='')AND tenant_id=#{tenantId}

