UPDATE model_usage
SET call_status = 'cancelled', finish_reason = #{reason}
WHERE user_id = #{userId} AND session_id = #{sessionId} AND run_id = #{runId}
  AND call_status = 'running' AND deleted = 0
AND (tenant_id IS NULL OR tenant_id='')AND tenant_id=#{tenantId}
